export function ThemeVariant({
  heading = "{{heading}}",
  themeVariant = "{{themeVariant}}",
  accent = "{{accent}}",
  showCard = {{showCard}},
}) {
  const palette = {
    light: { background: "#FAF7F2", color: "#241430" },
    dark: { background: "#241430", color: "#FAF7F2" },
    "high-contrast": { background: "#000000", color: "#ffffff" },
  }[themeVariant];
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", padding: 20, borderRadius: 12, width: 280, boxSizing: "border-box", ...palette }}>
      <p style={{ margin: "0 0 4px", fontWeight: 700, fontSize: 16 }}>{heading}</p>
      <p style={{ margin: "0 0 14px", fontSize: 11, opacity: .7 }}>theme: {themeVariant}</p>
      {showCard && <div style={{ padding: 12, borderRadius: 8, border: `${themeVariant === "high-contrast" ? 3 : 2}px solid ${accent}`, fontSize: 12 }}>Nested card inherits the theme</div>}
    </div>
  );
}
